请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-006

=== 用户原始指令 (query.txt) ===
搞个健身卡,主要是图表,带数字一行,点开能进app,读日历,红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个健身卡,主要是图表,带数字一行,点开能进app,读日历,红色危险提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "ui": {
      "title": {
        "type": "string",
        "description": "健身卡标题",
        "sampleValue": "健身日历"
      },
      "loadScore": {
        "type": "number",
        "description": "训练负荷仪表当前值",
        "sampleValue": 82
      },
      "loadTotal": {
        "type": "number",
        "description": "训练负荷仪表总值",
        "sampleValue": 100
      },
      "loadText": {
        "type": "string",
        "description": "训练负荷数字展示文本",
        "sampleValue": "82"
      },
      "loadLabel": {
        "type": "string",
        "description": "训练负荷说明",
        "sampleValue": "负荷偏高"
      },
      "alertText": {
        "type": "string",
        "description": "红色危险状态提示",
        "sampleValue": "危险"
      }
    },
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "当天日历中的健身日程列表",
          "sampleValue": [
            {
              "entityName": "日历",
              "entityId": "fitness-calendar-sample",
              "title": "跑步训练",
              "dtStart": "18:30",
              "dtEnd": "19:30"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条健身日程",
            "properties": {
              "entityName": {
                "type": "string",
                "description": "内容类别",
                "sampleValue": "日历"
              },
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符",
                "sampleValue": "fitness-calendar-sample"
              },
              "title": {
                "type": "string",
                "description": "日程标题",
                "sampleValue": "跑步训练"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间",
                "sampleValue": "18:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间",
                "sampleValue": "19:30"
              }
            }
          }
        }
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "日历数据加载状态",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动/跑步图标，适合用于健身、跑步训练和运动日程识别。"
    }
  ]
}

